const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point1 = ee.Geometry.Point([-79.198692, 43.244129]);
  const point2 = ee.Geometry.Point([-79.069485, 43.263113]);
  const area1 = point1.buffer(500); // 500m buffer around the point
  const area2 = point2.buffer(500);

  // Use a wider date range to increase chance of finding a clear image
  const startDate = '2021-02-01';
  const endDate = '2021-02-08';

  // 2. Data Acquisition & Cloud Masking
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to 0, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                   .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  const s2Collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
                        .filterDate(startDate, endDate)
                        .filterBounds(point1.union(point2));

  if (s2Collection.size().getInfo() === 0) {
      console.log('Evidence: No Sentinel-2 images found for the specified date range.');
      console.log('B');
      return;
  }

  const cloudMaskedCollection = s2Collection.map(maskS2clouds);
  const composite = cloudMaskedCollection.median(); // Create a single composite image

  // 3. Processing - Calculate NDVI
  const addNDVI = function(image) {
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return image.addBands(ndvi);
  };
  const imageWithNDVI = addNDVI(composite);
  const ndviBand = imageWithNDVI.select('NDVI');

  // 4. Calculation & Validation
  const scale = 30; // Use a coarser scale to ensure computation completes

  const ndviStats1 = ndviBand.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: area1,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const ndviStats2 = ndviBand.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: area2,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const ndvi1 = ndviStats1['NDVI'];
  const count1 = ndviStats1['NDVI_count'];
  const ndvi2 = ndviStats2['NDVI'];
  const count2 = ndviStats2['NDVI_count'];

  console.log(`Location 1 NDVI: ${ndvi1 !== null ? ndvi1.toFixed(4) : 'N/A'}, Valid Pixels: ${count1}`);
  console.log(`Location 2 NDVI: ${ndvi2 !== null ? ndvi2.toFixed(4) : 'N/A'}, Valid Pixels: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log('Evidence: One or both areas were completely cloud-covered or had no data.');
    console.log('C2');
    return;
  }

  if (ndvi1 === null || ndvi2 === null) {
    console.log('Evidence: Calculation failed, returned a null value for NDVI.');
    console.log('C3');
    return;
  }

  // Both points are in water in winter, NDVI will be negative. "Greener" means a less negative (higher) NDVI.
  if (ndvi1 > ndvi2) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log('D');
});
